from pathlib import Path
import json, math, shutil, sys
import pandas as pd
import numpy as np

R=Path(r'C:/Users/user/Documents/Codex/2026-11-23/a/outputs/Week6_Data_Analytics')
S=Path(sys.argv[1]) if len(sys.argv)>1 else Path(__file__).resolve().parents[1]/'data/source_copy.csv'
T=['AAPL','MSFT','AMZN','GOOGL','XOM']
for d in ['data','scripts','dashboard','reports','evidence']:(R/d).mkdir(parents=True,exist_ok=True)
d=pd.read_csv(S,parse_dates=['date']).sort_values(['symbol','date']).reset_index(drop=True)
g=d.groupby('symbol',sort=False)
d['year']=d.date.dt.year; d['month']=d.date.dt.month; d['quarter']=d.date.dt.quarter
d['daily_change']=g.close.diff(); d['daily_return']=g.close.pct_change(fill_method=None)
d['daily_range']=d.high-d.low
d['ma_20']=g.close.transform(lambda s:s.rolling(20,min_periods=20).mean())
d['ma_50']=g.close.transform(lambda s:s.rolling(50,min_periods=50).mean())
symbols=sorted(d.symbol.unique()); dates=d.date.nunique(); a=d.date.min().date().isoformat(); b=d.date.max().date().isoformat()
miss=d.isna().sum().to_dict(); dup=int(d.duplicated(['symbol','date']).sum()); zero=int(d.volume.eq(0).sum())
cov=d.groupby('symbol').agg(records=('date','size'),trading_dates=('date','nunique')).reset_index(); incomplete=int((cov.trading_dates<dates).sum())
bad=d[['open','high','low','close']].notna().all(axis=1)&((d.high<d[['open','close','low']].max(axis=1))|(d.low>d[['open','close']].min(axis=1)))
ext=d.loc[d.daily_return.abs()>.25,['symbol','date','close','daily_return']].sort_values('daily_return',key=lambda s:s.abs(),ascending=False)
sel=d[d.symbol.isin(T)].copy(); p=sel.pivot(index='date',columns='symbol',values='close').dropna(subset=T); r=p.pct_change(fill_method=None)
summary=[]
for s in T:
 x=sel[sel.symbol.eq(s)].sort_values('date'); z=r[s].dropna()
 summary.append(dict(symbol=s,records=len(x),common_period_return=float(p[s].iloc[-1]/p[s].iloc[0]-1),mean_daily_return=float(z.mean()),daily_vol=float(z.std()),annualized_vol=float(z.std()*math.sqrt(252)),mean_volume=float(x.volume.mean()),mean_close=float(x.close.mean()),max_close=float(x.close.max()),min_close=float(x.close.min())))
stats=dict(rows=len(d),columns=7,symbols=len(symbols),distinct_dates=int(dates),start=a,end=b,missing={k:int(v) for k,v in miss.items()},duplicate_keys=dup,zero_volume=zero,incomplete_symbols=incomplete,ohl_violations=int(bad.sum()),large_returns=len(ext),common_dates=len(p))
shutil.copy2(S,R/'data/source_copy.csv'); sel.to_csv(R/'data/selected_stocks_prepared.csv',index=False)
cov.to_csv(R/'reports/symbol_coverage.csv',index=False); pd.DataFrame(summary).to_csv(R/'reports/selected_stock_kpis.csv',index=False)
d.nlargest(10,'close')[['symbol','date','close']].to_csv(R/'reports/highest_closing_observations.csv',index=False)
d.nsmallest(10,'close')[['symbol','date','close']].to_csv(R/'reports/lowest_closing_observations.csv',index=False)
d.nlargest(10,'volume')[['symbol','date','volume']].to_csv(R/'reports/highest_volume_observations.csv',index=False)
ext.to_csv(R/'reports/large_daily_return_flags.csv',index=False)
d.loc[d.volume.eq(0),['symbol','date','volume']].to_csv(R/'reports/zero_volume_observations.csv',index=False)
df_ohlc=d.loc[bad,['symbol','date','open','high','low','close']]
df_ohlc.to_csv(R/'reports/ohlc_bound_violations.csv',index=False)
json.dump(stats,open(R/'reports/data_quality_summary.json','w'),indent=2)

checks=[]
for s in T:
 x=sel[sel.symbol.eq(s)].sort_values('date').reset_index(drop=True); i=20
 expected=(x.loc[i,'close']-x.loc[i-1,'close'])/x.loc[i-1,'close']
 checks.append([s+' daily return row 20',x.loc[i,'daily_return'],expected,abs(x.loc[i,'daily_return']-expected)<1e-12])
x=sel[sel.symbol.eq('AAPL')].sort_values('date').reset_index(drop=True); ex=x.loc[11:30,'close'].mean()
checks += [['AAPL SMA20 row 30',x.loc[30,'ma_20'],ex,abs(x.loc[30,'ma_20']-ex)<1e-12],['source row count',len(d),497472,len(d)==497472],['unique symbol-date keys',len(d[['symbol','date']].drop_duplicates()),len(d),dup==0]]
pd.DataFrame(checks,columns=['check','calculated','independent_expected','pass']).to_csv(R/'evidence/validation_checks.csv',index=False)

kpis=[['Daily price change','Close(t)-Close(t-1), by symbol','Absolute move; raw price levels vary.'],['Daily percentage return','Close(t)/Close(t-1)-1','Scale-free historical close-to-close change; not dividend adjusted.'],['Daily range','High-Low','Intraday spread; missing inputs remain missing.'],['20/50-day average','Simple mean over current and prior 19/49 closes','Full window required; descriptive only.'],['Mean daily return','Mean of valid daily returns','Historical average, outlier sensitive.'],['Daily volatility','Sample standard deviation of returns','Historical dispersion.'],['Annualized volatility','Daily sample SD times sqrt(252)','Trading-session convention; not forecast.'],['Mean volume','Mean shares traded daily','Not transaction value or revenue.'],['Common-period return','Last common-date close / first common-date close - 1','Selected stocks use shared dates; excludes dividends.']]
pd.DataFrame(kpis,columns=['KPI','Definition / method','Caveat']).to_csv(R/'reports/KPI_definitions.csv',index=False)

ser=[]
for s in T:
 x=sel[sel.symbol.eq(s)].sort_values('date')
 vals={}
 for k in ['close','open','high','low','volume','daily_return','daily_range','ma_20','ma_50']:
  z=x[k].astype(object); z=z.where(np.isfinite(x[k]),None); vals[k]=z.tolist()
 ser.append(dict(symbol=s,dates=x.date.dt.strftime('%Y-%m-%d').tolist(),**vals))
payload=json.dumps(dict(series=ser,summary=summary,stats=stats,coverage=cov.to_dict('records')),allow_nan=False)
page='''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Market Intelligence Dashboard</title><script src="https://cdn.plot.ly/plotly-2.35.2.min.js"></script><style>body{font:15px Arial;background:#f1f5f9;color:#123;padding:20px;max-width:1300px;margin:auto}.hero,.box{background:white;padding:16px;border-radius:12px;margin:10px 0}.hero{background:#12334d;color:white}.tabs button{padding:10px;margin:4px;border:0;border-radius:7px;cursor:pointer}.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.chart{height:380px}.hidden{display:none}.warn{background:#fff1d8;padding:12px}@media(max-width:700px){.grid{grid-template-columns:1fr}}</style></head><body><div class="hero"><h1>S&amp;P 500 Market Intelligence</h1>Data Analytics | Supplied 2014-2017 historical file</div><div class="box">Symbols <select id="sym" multiple size="1"></select> From <input id="from" type="date"> To <input id="to" type="date"></div><div class="tabs"><button data-p="overview">Market Overview</button><button data-p="price">Price Performance</button><button data-p="returns">Returns &amp; Volatility</button><button data-p="volume">Trading Volume</button></div><section id="overview"><div class="box" id="quality"></div><div class="grid"><div class="box chart" id="closeAll"></div><div class="box chart" id="coverage"></div><div class="box chart" id="avgClose"></div></div></section><section id="price" class="hidden"><div class="grid"><div class="box chart" id="close"></div><div class="box chart" id="ohlc"></div><div class="box chart" id="ma"></div><div class="box chart" id="range"></div></div></section><section id="returns" class="hidden"><div class="grid"><div class="box chart" id="ret"></div><div class="box chart" id="dist"></div><div class="box chart" id="vol"></div></div></section><section id="volume" class="hidden"><div class="grid"><div class="box chart" id="volume"></div><div class="box chart" id="avg"></div><div class="box chart" id="scatter"></div></div></section><p class="warn">Historical data only. No adjusted-close, currency or complete corporate-action information is supplied. Past performance is not a guarantee or investment advice. Plotly loads from CDN and requires internet.</p><div class="box">Returns are grouped by symbol; moving averages use 20/50 trading observations; annualized volatility = sample daily SD × √252. Volume is shares traded.</div><script>const D=__DATA__,C=['#176b87','#f08c46','#438a5e','#7868a6','#ca5365'],sel=document.querySelector('#sym');D.series.forEach(s=>sel.add(new Option(s.symbol,s.symbol,true,true)));document.querySelector('#from').value='2014-01-01';document.querySelector('#to').value='2017-12-31';function ds(){let a=document.querySelector('#from').value,b=document.querySelector('#to').value;return D.series.filter(s=>[...sel.selectedOptions].some(o=>o.value===s.symbol)).map(s=>({...s,I:s.dates.map((d,i)=>d>=a&&d<=b?i:-1).filter(i=>i>=0)}))}function traces(k){return ds().map((s,j)=>({x:s.I.map(i=>s.dates[i]),y:s.I.map(i=>s[k][i]),name:s.symbol,mode:'lines',type:'scatter',line:{color:C[j%5]}}))}function plot(id,title,y,tr,extra={}){Plotly.react(id,tr,{title,paper_bgcolor:'white',plot_bgcolor:'white',margin:{t:45,b:55,l:55,r:15},legend:{orientation:'h',y:-.2},xaxis:{gridcolor:'#ddd'},yaxis:{title:y,gridcolor:'#ddd'},...extra},{responsive:true,displaylogo:false})}function up(){let ss=D.summary.filter(s=>[...sel.selectedOptions].some(o=>o.value===s.symbol));document.querySelector('#quality').innerHTML=`<b>Whole file:</b> ${D.stats.rows.toLocaleString()} rows; ${D.stats.symbols} symbols; ${D.stats.distinct_dates} dates, ${D.stats.start} to ${D.stats.end}. Missing open/high/low ${D.stats.missing.open}/${D.stats.missing.high}/${D.stats.missing.low}; zero-volume ${D.stats.zero_volume}; duplicate keys ${D.stats.duplicate_keys}; incomplete histories ${D.stats.incomplete_symbols}. Selected average closes: ${ss.map(s=>s.symbol+' '+s.mean_close.toFixed(2)).join(', ')}.`;plot('closeAll','Selected stock closing prices','Close',traces('close'));Plotly.react('coverage',[{x:D.coverage.map(x=>x.symbol),y:D.coverage.map(x=>x.records),type:'bar',marker:{color:'#176b87'}}],{title:'Records by stock symbol',xaxis:{tickangle:-60},yaxis:{title:'Rows'}});Plotly.react('avgClose',[{x:ss.map(s=>s.symbol),y:ss.map(s=>s.mean_close),type:'bar',marker:{color:C}}],{title:'Average closing price: selected stocks',yaxis:{title:'Raw close'}});plot('close','Closing price','Price',traces('close'));let t=[];ds().forEach((s,j)=>['open','high','low','close'].forEach(k=>t.push({x:s.I.map(i=>s.dates[i]),y:s.I.map(i=>s[k][i]),name:s.symbol+' '+k,mode:'lines',visible:k==='close'?'legendonly':true,line:{color:C[j%5],dash:{open:'dot',high:'dash',low:'dashdot',close:'solid'}[k]}})));plot('ohlc','Open, high, low and close','Price',t);t=[];ds().forEach((s,j)=>['close','ma_20','ma_50'].forEach(k=>t.push({x:s.I.map(i=>s.dates[i]),y:s.I.map(i=>s[k][i]),name:s.symbol+' '+k,mode:'lines',visible:k==='close'?'legendonly':true,line:{color:C[j%5],dash:{close:'solid',ma_20:'dash',ma_50:'dot'}[k]}})));plot('ma','Close with moving averages','Price',t);plot('range','Daily high-low range','Range',traces('daily_range'));plot('ret','Daily percentage return','Return',traces('daily_return'),{yaxis:{title:'Return',tickformat:'.1%'}});plot('dist','Return distribution','Count',ds().map((s,j)=>({x:s.I.map(i=>s.daily_return[i]).filter(x=>x!==null),name:s.symbol,type:'histogram',opacity:.5,marker:{color:C[j%5]}})),{barmode:'overlay'});Plotly.react('vol',ss.map((s,j)=>({x:[s.symbol],y:[s.annualized_vol],type:'bar',marker:{color:C[j%5]}})),{title:'Annualized historical volatility',yaxis:{tickformat:'.0%'}});plot('volume','Daily volume','Shares',traces('volume'));Plotly.react('avg',ss.map((s,j)=>({x:[s.symbol],y:[s.mean_volume],type:'bar',marker:{color:C[j%5]}})),{title:'Average daily volume',yaxis:{title:'Shares'}});plot('scatter','Volume versus daily return','Return',ds().map((s,j)=>({x:s.I.map(i=>s.volume[i]),y:s.I.map(i=>s.daily_return[i]),name:s.symbol,type:'scattergl',mode:'markers',marker:{color:C[j%5],opacity:.4,size:5}})),{xaxis:{title:'Shares traded',type:'log'},yaxis:{title:'Daily return',tickformat:'.1%'}})}document.querySelectorAll('.tabs button').forEach(b=>b.onclick=()=>{document.querySelectorAll('section').forEach(x=>x.classList.toggle('hidden',x.id!==b.dataset.p));setTimeout(()=>dispatchEvent(new Event('resize')),100)});[sel,document.querySelector('#from'),document.querySelector('#to')].forEach(x=>x.onchange=up);up()</script></body></html>'''.replace('__DATA__',payload)
